CREATE TABLE IF NOT EXISTS articles (id BIGSERIAL PRIMARY KEY, title VARCHAR(255) NOT NULL, description VARCHAR(255) NOT NULL, body TEXT NOT NULL, user_id BIGINT NOT NULL, CONSTRAINT fk_articles_user_id__id FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_Articles_unsigned_integer_id CHECK (id BETWEEN 0 AND 4294967295));
CREATE SEQUENCE IF NOT EXISTS Articles_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;